396	    /**
397	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
398	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
399	     *
400	     * @return list<AssetFolder>
401	     */
402	    public function getBreadcrumbTrail(): array
403	    {
404	        if ($this->activeFolderId === null) {
405	            return [];
406	        }
407	
408	        $folders = $this->allFolders();
409	        $trail = [];
410	        $id = $this->activeFolderId;
411	
412	        while ($id !== null) {
413	            $folder = $folders->firstWhere('id', $id);
414	            if (! $folder instanceof AssetFolder) {
415	                // folder eliminata sotto i piedi: torna a root
416	                $this->activeFolderId = null;
417	
418	                return [];
419	            }
420	
421	            array_unshift($trail, $folder);
422	            $id = $folder->parent_id;
423	        }
424	
425	        return $trail;
426	    }
