666	    /**
667	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
668	     * I file finiscono nella collection asset del record (disco scoped).
669	     */
670	    public function uploadAssetsAction(): Action
671	    {
672	        return Action::make('uploadAssets')
673	            ->label(__('digital-hub::assets.upload'))
674	            ->icon(Heroicon::OutlinedArrowUpTray)
675	            ->modalHeading(__('digital-hub::assets.upload_heading'))
676	            ->schema([
677	                FileUpload::make('files')
678	                    ->label(__('digital-hub::assets.files_field'))
679	                    ->multiple()
680	                    ->required()
681	                    ->storeFiles(false),
682	            ])
683	            ->action(function (array $data): void {
684	                $owner = $this->resolveOwner();
685	                $files = $data['files'] ?? [];
686	                if (! is_array($files)) {
687	                    return;
688	                }
689	
690	                $count = 0;
691	                foreach ($files as $file) {
692	                    if (! $file instanceof TemporaryUploadedFile) {
693	                        continue;
694	                    }
695	
696	                    $media = $owner->addMedia($file)
697	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
698	                        ->toMediaCollection($owner->assetsCollection());
699	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
700	
701	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
702	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
703	                    /** @disregard P1013 */
704	                    $user = auth()->user();
705	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
706	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
707	
708	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
709	                    // job in coda: il media entra "pending" finché il job non lo chiude
710	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
711	                    $media->save();
712	
713	                    $this->dispatchProcessing($media);
714	                    $count++;
715	                }
716	
717	                if ($count > 0) {
718	                    Notification::make()
719	                        ->success()
720	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
721	                        ->send();
722	                }
723	            });
724	    }
