831	     * Sezioni collassabili con i metadati estratti grezzi (`extracted_metadata`),
832	     * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
833	     * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
834	     * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
835	     * metadati (media non ancora processato).
836	     *
837	     * @return list<Section>
838	     */
839	    private function assetMetadataSections(Media $media): array
840	    {
841	        $metadata = ExtractedMetadata::forMedia($media);
842	
843	        $labels = [
844	            'common' => __('digital-hub::assets.meta_block_common'),
845	            'exif' => 'EXIF',
846	            'iptc' => 'IPTC',
847	            'xmp' => 'XMP',
848	        ];
849	
850	        $sections = [];
851	        foreach ($labels as $key => $label) {
852	            $block = $metadata[$key] ?? null;
853	            if (! is_array($block)) {
854	                continue;
855	            }
856	
857	            $flat = ExtractedMetadata::flatten($block);
858	            if ($flat === []) {
859	                continue;
860	            }
861	
862	            $sections[] = Section::make($label)
863	                ->heading('')
864	                // ->collapsible()
865	                // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
866	                ->schema([
867	                    Fieldset::make($label)
868	                        ->columnSpanFull()
869	                        ->columns(1)
870	                        ->contained(false)
871	                        ->schema([
872	                            KeyValueEntry::make("meta_{$key}")
873	                                ->hiddenLabel()
874	                                ->state($flat)
875	                                ->keyLabel(__('digital-hub::assets.meta_key'))
876	                                ->valueLabel(__('digital-hub::assets.meta_value')),
877	                        ]),
878	                ]);
879	        }
880	
881	        return $sections;
882	    }
