1314	    private function appendFolderOptions(?int $parentId, int $depth, array &$options, ?int $excludeId = null): void
1315	    {
1316	        foreach ($this->allFolders()->where('parent_id', $parentId) as $folder) {
1317	            if ($excludeId !== null && $folder->id === $excludeId) {
1318	                continue; // salta la folder e (non ricorrendo) il suo sottoalbero
1319	            }
1320	
1321	            $options[$folder->id] = str_repeat('— ', $depth) . $folder->name;
1322	            $this->appendFolderOptions($folder->id, $depth + 1, $options, $excludeId);
1323	        }
