72	    /**
73	     * Appiattisce un blocco di metadati (anche annidato, es. le sezioni EXIF) in
74	     * coppie `chiave => valore scalare` (stringa), adatte a una resa key/value.
75	     * Le chiavi annidate diventano dot-notation (es. `EXIF.ISO`,
76	     * `GPS.GPSLatitude`, `Keywords.0`); i valori non scalari vengono scartati.
77	     *
78	     * @param array<array-key, mixed> $data
79	     * @return array<string, string>
80	     */
81	    public static function flatten(array $data, string $prefix = ''): array
82	    {
83	        $flat = [];
84	        foreach ($data as $key => $value) {
85	            $composite = $prefix === '' ? (string) $key : $prefix . '.' . $key;
86	
87	            if (is_array($value)) {
88	                $flat += self::flatten($value, $composite);
89	            } elseif (is_bool($value)) {
90	                $flat[$composite] = $value ? 'true' : 'false';
91	            } elseif (is_scalar($value)) {
92	                $flat[$composite] = (string) $value;
93	            }
94	        }
95	
96	        return $flat;
97	    }
98	}
